#ifndef IOT_GATEWAY_ALERT_H
#define IOT_GATEWAY_ALERT_H

#include "processor.h"

/* Types of alerts generated by the gateway. */
typedef enum {
    ALERT_LEVEL_WARNING = 0,
    ALERT_LEVEL_CRITICAL
} alert_level_t;

/* Alert event containing the processed temperature information. */
typedef struct {
    double temperature_c;
    time_t timestamp_unix_s;
    sensor_source_t source;
    alert_level_t level;
} alert_event_t;

/* Alert generation outcomes. */
typedef enum {
    ALERT_GENERATION_ERROR = -1,
    ALERT_GENERATION_NONE = 0,
    ALERT_GENERATION_CREATED = 1
} alert_generation_status_t;

/* Generate an alert from a processed temperature result. */
alert_generation_status_t alert_generate(
    const temperature_result_t *result,
    alert_event_t *out_alert
);

#endif /* IOT_GATEWAY_ALERT_H */
